-- Isolated CI checks for Stage 4. Cloud has a broader extension-free assertion
-- file at tests/db/judge.cloud.sql. Every fixture and key configuration rolls back.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','quarrel_private.judge_messages','SELECT'),'No direct judge-history reads');
select ok(not has_table_privilege('authenticated','quarrel_private.judge_messages','INSERT'),'No direct judge-message writes');
select ok(not has_table_privilege('authenticated','quarrel_private.judge_settings','SELECT'),'Server hash stays private');
select ok(not has_table_privilege('authenticated','quarrel_private.judge_settings','UPDATE'),'Members cannot change server authority');
select ok((select relrowsecurity from pg_class where oid='quarrel_private.judge_messages'::regclass),'Judge history has defense-in-depth RLS');
select ok((select relrowsecurity from pg_class where oid='quarrel_private.judge_settings'::regclass),'Judge settings have RLS');
select ok(not exists(select 1 from pg_publication_tables where schemaname='quarrel_private' and tablename in ('judge_messages','judge_settings')),'Judge text and keyhash excluded from Realtime');
select ok(not has_function_privilege('authenticated','quarrel_private.reconcile_judge(uuid)','EXECUTE'),'Recovery helper private');
select ok(not has_function_privilege('anon','public.claim_quarrel_judge_work(text)','EXECUTE'),'Worker requires authenticated role');
select ok(not has_function_privilege('anon','public.finish_quarrel_judge_work(uuid,jsonb,text)','EXECUTE'),'Public API role cannot forge response');

insert into auth.users(id,aud,role,is_anonymous,created_at,updated_at) values
 ('a4444444-4444-4444-8444-444444444444','authenticated','authenticated',true,now(),now()),
 ('b5555555-5555-4555-8555-555555555555','authenticated','authenticated',true,now(),now());
update quarrel_private.judge_settings set key_hash=sha256(convert_to('isolated-ci-server-capability-test-only','UTF8')) where singleton;
create temporary table judge_test(snapshot jsonb, job jsonb, first_deadline timestamptz);
grant select,insert,update on judge_test to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='a4444444-4444-4444-8444-444444444444';
insert into judge_test(snapshot) values(public.create_quarrel_room('Judge host'));
-- Preserve this legacy Jungle judge fixture independently of new-room defaults.
select public.set_quarrel_theme('jungle');
select is(public.get_quarrel_room()->'judge','null'::jsonb,'New room still starts in lobby without judge');
select public.propose_quarrel_debate('Who should wash dishes?','I cooked','I washed all week',0);
select public.set_quarrel_ready(true);
set local request.jwt.claim.sub='b5555555-5555-4555-8555-555555555555';
select public.join_quarrel_room((select snapshot->>'code' from judge_test),'Judge guest');
select public.approve_quarrel_debate(1);select public.set_quarrel_ready(true);
set local request.jwt.claim.sub='a4444444-4444-4444-8444-444444444444';
select throws_ok($$select public.start_quarrel_judged_debate(1,'browser-forgery','demo',2,'{}')$$,'P0001','JUDGE_SERVER_UNAUTHORIZED','Member token cannot act as worker');
update judge_test set snapshot=public.start_quarrel_judged_debate(1,'isolated-ci-server-capability-test-only','demo',2,'{"themeId":"jungle","introduction":"Welcome {playerA} and {playerB}: {topic}","opening":"{speaker}, opening time.","rebuttal":"{speaker}, rebuttal time.","questions":"{speaker}, answer your clarification question.","complete":"Record complete. No winner."}');
update judge_test set first_deadline=(snapshot #>> '{debate,turnDeadline}')::timestamptz;
select is((select snapshot #>> '{judge,mode}' from judge_test),'demo','Judge mode saved');
select is((select snapshot #>> '{judge,maxMessagesPerTurn}' from judge_test),'2','Two message default');
select is((select snapshot #>> '{judge,messages,0,kind}' from judge_test),'introduction','Introduction persisted');
select is((select snapshot #> '{debate,questions}' from judge_test),'[]'::jsonb,'No premature placeholder questions');
update judge_test set snapshot=public.begin_quarrel_judge_message('Can you examine the arrangement?',1,0,'c6666666-6666-4666-8666-666666666666','isolated-ci-server-capability-test-only');
select is((select snapshot #>> '{judge,messagesUsed}' from judge_test),'1','One reserved message');
select is((select snapshot #>> '{debate,turnIndex}' from judge_test),'0','Ask does not end turn');
select is((select (snapshot #>> '{debate,turnDeadline}')::timestamptz from judge_test),(select first_deadline from judge_test),'Ask does not reset clock');
select is((select jsonb_array_length(snapshot #> '{debate,history}') from judge_test),0,'Ask does not submit official argument');
select is(public.begin_quarrel_judge_message('Can you examine the arrangement?',1,0,'c6666666-6666-4666-8666-666666666666','isolated-ci-server-capability-test-only') #>> '{judge,pendingRequestId}',(select snapshot #>> '{judge,pendingRequestId}' from judge_test),'Duplicate request recovers same message');
update judge_test set job=public.claim_quarrel_judge_work('isolated-ci-server-capability-test-only');
select is((select job->>'mode' from judge_test),'demo','Claim keeps saved provider mode');
select is((select job #> '{context,arguments}' from judge_test),'[]'::jsonb,'Private openings excluded from shared judge');
select is(public.claim_quarrel_judge_work('isolated-ci-server-capability-test-only'),null::jsonb,'Claimed job never issued twice');
select throws_ok($$select public.finish_quarrel_judge_work((select (job->>'id')::uuid from judge_test),'[{"text":"not an object"}]','isolated-ci-server-capability-test-only')$$,'P0001','INVALID_JUDGE_RESPONSE','Malformed response rejected');
update judge_test set snapshot=public.finish_quarrel_judge_work((job->>'id')::uuid,'{"text":"What agreement did each of you understand?","reaction":"questioning","source":"demo"}','isolated-ci-server-capability-test-only');
select is((select snapshot #>> '{judge,pendingRequestId}' from judge_test),null::text,'Completion clears pending state');
select is((select snapshot #>> '{judge,messages,1,text}' from judge_test),'What agreement did each of you understand?','Reply saved');
set local request.jwt.claim.sub='b5555555-5555-4555-8555-555555555555';
select is(public.get_quarrel_room() #> '{judge,messages}',(select snapshot #> '{judge,messages}' from judge_test),'Peer gets identical conversation');
select throws_ok($$select public.begin_quarrel_judge_message('Out of turn',1,0,gen_random_uuid(),'isolated-ci-server-capability-test-only')$$,'P0001','NOT_YOUR_TURN','Only active player messages');
set local request.jwt.claim.sub='a4444444-4444-4444-8444-444444444444';
select public.submit_quarrel_argument('I cooked dinner.',1,0);
set local request.jwt.claim.sub='b5555555-5555-4555-8555-555555555555';select public.submit_quarrel_argument('I washed dishes all week.',1,1);
set local request.jwt.claim.sub='a4444444-4444-4444-8444-444444444444';select public.submit_quarrel_argument('Cooking took an hour.',1,2);
set local request.jwt.claim.sub='b5555555-5555-4555-8555-555555555555';update judge_test set snapshot=public.submit_quarrel_argument('We agreed to share chores.',1,3);
select is((select snapshot #>> '{judge,preparingQuestions}' from judge_test),'true','Question preparation starts after rebuttals');
select is((select snapshot #>> '{debate,activeSlot}' from judge_test),null::text,'No active player during generation');
select is((select snapshot #>> '{debate,turnDeadline}' from judge_test),null::text,'Generation does not consume player clock');
set local request.jwt.claim.sub='a4444444-4444-4444-8444-444444444444';
select throws_ok($$select public.submit_quarrel_argument('Premature answer',1,4)$$,'P0001','JUDGE_PREPARING_QUESTIONS','Cannot bypass question generation');
update judge_test set job=public.claim_quarrel_judge_work('isolated-ci-server-capability-test-only');
select is((select jsonb_array_length(job #> '{context,arguments}') from judge_test),4,'Both sides arguments available for clarification');
select is(public.claim_quarrel_judge_work('isolated-ci-server-capability-test-only'),null::jsonb,'Question generation claimed only once');
update judge_test set snapshot=public.finish_quarrel_judge_work((job->>'id')::uuid,'{"text":"Two points to clarify.","reaction":"questioning","source":"demo","questions":[{"slot":"A","text":"What was the cooking and cleaning arrangement?","source":"demo"},{"slot":"B","text":"How did you define an equal share of chores?","source":"demo"}]}','isolated-ci-server-capability-test-only');
select is((select snapshot #>> '{judge,preparingQuestions}' from judge_test),'false','Validated questions persist before answer turn');
select is((select jsonb_array_length(snapshot #> '{debate,questions}') from judge_test),2,'Both questions persisted');
select is((select snapshot #>> '{debate,activeSlot}' from judge_test),'A','A answers first');
select ok((select (snapshot #>> '{debate,turnDeadline}')::timestamptz > clock_timestamp()+interval '29 seconds' from judge_test),'Question generation leaves full 30 seconds');
select public.submit_quarrel_argument('No explicit arrangement.',1,4);
set local request.jwt.claim.sub='b5555555-5555-4555-8555-555555555555';update judge_test set snapshot=public.submit_quarrel_argument('Alternating chores.',1,5);
select is((select snapshot #>> '{debate,phase}' from judge_test),'verdict','Debate reaches existing placeholder completion');
select ok((select not(snapshot #> '{debate}' ? 'winner') from judge_test),'No actual winner introduced');
select is((select jsonb_array_length(snapshot #> '{debate,history}') from judge_test),6,'Six official entries remain separate from chat');
reset role;
select * from finish();
rollback;
